public ListNode sortList(ListNode head) {
    if (head == null || head.next == null) return head;

    int n = 0;
    for (ListNode cur = head; cur != null; cur = cur.next) n++;

    ListNode dummy = new ListNode(0);
    dummy.next = head;

    for (int size = 1; size < n; size *= 2) {
        ListNode prev = dummy, cur = dummy.next;
        while (cur != null) {
            ListNode left = cur;
            ListNode right = split(left, size);
            cur = split(right, size);          // start of the next block
            prev = mergeInto(prev, left, right);
        }
    }
    return dummy.next;
}

// Cut after `size` nodes; return the head of the remainder.
private ListNode split(ListNode head, int size) {
    for (int i = 1; head != null && i < size; i++) head = head.next;
    if (head == null) return null;
    ListNode rest = head.next;
    head.next = null;
    return rest;
}

// Merge a and b, append onto prev's tail, return the new tail node.
private ListNode mergeInto(ListNode prev, ListNode a, ListNode b) {
    ListNode tail = prev;
    while (a != null && b != null) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }
        else                { tail.next = b; b = b.next; }
        tail = tail.next;
    }
    tail.next = (a != null) ? a : b;
    while (tail.next != null) tail = tail.next;
    return tail;
}

